class Solution {
public:
    vector<vector<int>> res;
    vector<int> path;
    void go(vector<int>& nums, int start) {
        res.push_back(path);
        for (int i = start; i < (int)nums.size(); i++) {
            path.push_back(nums[i]);
            go(nums, i + 1);
            path.pop_back();
        }
    }
    vector<vector<int>> subsets(vector<int>& nums) {
        go(nums, 0);
        return res;
    }
};
